import AppKit
import Foundation
import ScriptingBridge

// Selectors verified against the header generated by
//   sdef /System/Applications/Music.app | sdp -fh --basename Music

@objc private protocol MusicArtworkScripting {
    var data: NSImage? { get }
}

@objc private protocol MusicTrackScripting {
    var name: String? { get }
    var artist: String? { get }
    var album: String? { get }
    var duration: Double { get }
    var favorited: Bool { get set }
    var persistentID: String? { get }
    func artworks() -> SBElementArray
}

@objc private protocol MusicApplicationScripting {
    var currentTrack: MusicTrackScripting? { get }
    var soundVolume: Int { get set }
    var playerState: UInt32 { get }
    var playerPosition: Double { get set }
    var mute: Bool { get set }
    var shuffleEnabled: Bool { get set }
    var songRepeat: UInt32 { get set }
    func nextTrack()
    func previousTrack()
    func playpause()
    func pause()
    func resume()
}

/// Drives Music.app over Apple Events.
///
/// MusicKit is deliberately not used: its `SystemMusicPlayer` — the only player that controls
/// the Music app — is marked `@available(macOS, unavailable)`, and `ApplicationMusicPlayer`
/// drives an app-private queue instead. Apple Events are the only route on macOS.
final class AppleMusicProvider: MediaProvider {
    static let bundleIdentifier = "com.apple.Music"

    let id = ProviderID.appleMusic
    let displayName = "Apple Music"

    /// Music.app has a real `mute` property and a writable `favorited`, so unlike Spotify
    /// both are native here.
    let capabilities: ProviderCapabilities = [
        .seek, .volume, .nativeMute, .shuffle, .repeatMode, .repeatOne, .favorite,
    ]

    private enum RepeatCode {
        static let off = fourCharCode("kRpO")
        static let one = fourCharCode("kRp1")
        static let all = fourCharCode("kAll")

        static func mode(from raw: UInt32) -> RepeatMode {
            switch raw {
            case one: return .one
            case all: return .all
            default:  return .off
            }
        }

        static func code(for mode: RepeatMode) -> UInt32 {
            switch mode {
            case .off: return off
            case .one: return one
            case .all: return all
            }
        }
    }

    private let client = ScriptingBridgeClient(
        bundleIdentifier: AppleMusicProvider.bundleIdentifier,
        appName: "Music"
    )

    func isRunning() -> Bool { client.isRunning() }

    func snapshot() async throws -> PlayerSnapshot {
        try await client.run { app in
            let music = unsafeBitCast(app, to: MusicApplicationScripting.self)

            let rawState = music.playerState
            let status = PlayerStateCode.status(from: rawState)

            var track: Track?
            if let raw = music.currentTrack, let name = raw.name, !name.isEmpty {
                track = Track(
                    id: raw.persistentID ?? name,
                    title: name,
                    artist: raw.artist ?? "",
                    album: raw.album ?? "",
                    duration: raw.duration,
                    // Music.app hands us real image data, covering both local files and
                    // Apple Music streaming tracks. Only fetched when something is playing,
                    // since it is the most expensive part of the round trip.
                    artwork: status == .stopped ? nil : Self.artwork(from: raw),
                    isFavorite: raw.favorited
                )
            }

            let muted = music.mute
            return PlayerSnapshot(
                track: track,
                status: status,
                position: music.playerPosition,
                volume: music.soundVolume,
                isMuted: muted,
                isShuffling: music.shuffleEnabled,
                repeatMode: RepeatCode.mode(from: music.songRepeat),
                capturedAt: Date()
            )
        }
    }

    private static func artwork(from track: MusicTrackScripting) -> ArtworkSource? {
        guard
            let artworks = track.artworks() as SBElementArray?,
            artworks.count > 0,
            let first = artworks.object(at: 0) as AnyObject?
        else { return nil }

        let artwork = unsafeBitCast(first, to: MusicArtworkScripting.self)
        guard
            let image = artwork.data,
            let tiff = image.tiffRepresentation,
            let rep = NSBitmapImageRep(data: tiff),
            let png = rep.representation(using: .png, properties: [:])
        else { return nil }
        return .data(png)
    }

    func play() async throws {
        // Music.app's `play` takes a parameter (`playOnce:`); `resume` is the no-argument
        // way to start the current track.
        try await client.run { unsafeBitCast($0, to: MusicApplicationScripting.self).resume() }
    }

    func pause() async throws {
        try await client.run { unsafeBitCast($0, to: MusicApplicationScripting.self).pause() }
    }

    func playPause() async throws {
        try await client.run { unsafeBitCast($0, to: MusicApplicationScripting.self).playpause() }
    }

    func nextTrack() async throws {
        try await client.run { unsafeBitCast($0, to: MusicApplicationScripting.self).nextTrack() }
    }

    func previousTrack() async throws {
        try await client.run { unsafeBitCast($0, to: MusicApplicationScripting.self).previousTrack() }
    }

    func seek(to position: TimeInterval) async throws {
        try await client.run { app in
            let music = unsafeBitCast(app, to: MusicApplicationScripting.self)
            music.playerPosition = max(0, position)
        }
    }

    func setVolume(_ volume: Int) async throws {
        let clamped = max(0, min(100, volume))
        try await client.run { app in
            let music = unsafeBitCast(app, to: MusicApplicationScripting.self)
            music.soundVolume = clamped
        }
    }

    func setMuted(_ muted: Bool) async throws {
        try await client.run { app in
            let music = unsafeBitCast(app, to: MusicApplicationScripting.self)
            music.mute = muted
        }
    }

    func setShuffle(_ enabled: Bool) async throws {
        try await client.run { app in
            let music = unsafeBitCast(app, to: MusicApplicationScripting.self)
            music.shuffleEnabled = enabled
        }
    }

    func setRepeat(_ mode: RepeatMode) async throws {
        try await client.run { app in
            let music = unsafeBitCast(app, to: MusicApplicationScripting.self)
            music.songRepeat = RepeatCode.code(for: mode)
        }
    }

    func setFavorite(_ favorite: Bool) async throws {
        try await client.run { app in
            let music = unsafeBitCast(app, to: MusicApplicationScripting.self)
            guard var track = music.currentTrack else { return }
            track.favorited = favorite
        }
    }
}
